import pandas as pd import os
def inspect_data(input_file='data_lt.csv'): """ Reads an Excel or CSV file and prints the first 20 rows to inspect its structure. """ try: # Try reading as an Excel file first df = pd.read_excel(input_file, header=None) print("Successfully loaded as Excel. First 20 rows:") print(df.head(20).to_string()) except Exception as e: print(f"Could not read as Excel, trying CSV: {e}") try: # If Excel fails, try reading as a CSV df = pd.read_csv(input_file, encoding='utf-8', header=None) print("Successfully loaded as CSV. First 20 rows:") print(df.head(20).to_string()) except Exception as e2: print(f"Could not read as CSV: {e2}") return
if __name__ == '__main__': script_dir = os.path.dirname(os.path.abspath(__file__)) input_path = os.path.join(script_dir, 'data_lt.csv') inspect_data(input_path)
